record.field:
# Filter active tours
active_tours = records.filtered(lambda r: r.status == 'active')
if not active_tours:
    raise UserError(_('No active tours selected!'))

if len(active_tours) == 1:
    # Single tour - open wizard
    action = active_tours[0].action_manual_generate_tour()
else:
    # Multiple tours - show selection dialog
    action = {
        'name': _('Select Tour for Manual Generation'),
        'type': 'ir.actions.act_window',
        'res_model': 'security.tour',
        'view_mode': 'list,form',
        'domain': [('id', 'in', active_tours.ids)],
        'context': {
            'default_status': 'active',
            'create': False,
            'edit': False
        }
    }
